INSERT INTO public.questions (question_text,option_a,option_b,option_c,option_d,correct_answer,explanation,tip,difficulty,source,is_verified,category_id)
SELECT v.qt,v.a,v.b,v.c,v.d,v.ca,v.ex,v.tp,v.df::public.difficulty_level,'AUTHORED',true,c.id
FROM (VALUES
('Um sinal de forma triangular com orla vermelha indica:','Uma obrigação','Um perigo iminente','Uma proibição','Uma informação útil','B','Os sinais triangulares com orla vermelha são sinais de perigo: avisam o condutor de um risco existente à frente.','Triângulo vermelho = atenção ao perigo que vem a seguir.','facil','sinais-de-transito'),
('Um sinal circular com fundo azul e símbolo branco indica:','Uma proibição','Uma obrigação','Um perigo','Um fim de restrição','B','Os sinais circulares azuis são sinais de obrigação: impõem um comportamento, como seguir numa direção.','Azul redondo manda fazer; vermelho redondo proíbe.','facil','sinais-de-transito'),
('O sinal STOP obriga o condutor a:','Reduzir a velocidade e prosseguir se a via estiver livre','Parar obrigatoriamente antes da linha de paragem e ceder passagem','Parar apenas quando existir trânsito','Buzinar antes de avançar','B','O sinal STOP obriga sempre à paragem completa do veículo, mesmo que a via esteja aparentemente livre.','STOP significa rodas totalmente paradas.','facil','sinais-de-transito'),
('Um sinal circular com orla vermelha e um número no centro significa:','Velocidade mínima obrigatória','Velocidade recomendada','Velocidade máxima permitida','Distância até à próxima localidade','C','O sinal de proibição com número indica a velocidade máxima que não pode ser excedida naquele troço.','Orla vermelha = limite que não se ultrapassa.','facil','sinais-de-transito'),
('As marcas rodoviárias longitudinais contínuas indicam que:','É permitido ultrapassar com cuidado','Não é permitido transpor a linha','Só motociclos podem transpor a linha','A via termina em breve','B','A linha contínua não pode ser transposta nem pisada, exceto em situações de emergência devidamente justificadas.','Contínua = barreira; descontínua = permissão condicionada.','facil','sinais-de-transito'),
('Um sinal quadrado ou retangular de fundo azul geralmente transmite:','Uma proibição','Uma informação','Um perigo','Uma penalização','B','Os sinais de forma quadrada ou retangular com fundo azul são sinais de informação e indicação.','Retângulo azul informa, não obriga.','facil','sinais-de-transito'),
('Perante um sinal luminoso amarelo fixo, o condutor deve:','Acelerar para passar','Parar antes do sinal, salvo se já não puder fazê-lo em segurança','Prosseguir sempre','Buzinar e passar','B','O amarelo fixo impõe a paragem antes do sinal, exceto quando o veículo está tão próximo que parar seria perigoso.','Amarelo não é ''passa depressa''; é ''prepara-te para parar''.','medio','sinais-de-transito'),
('Um sinal amarelo intermitente num cruzamento significa:','Passagem livre e prioritária','Prosseguir com precaução, cedendo passagem conforme as regras','Paragem obrigatória','Proibido virar','B','O amarelo intermitente avisa que o cruzamento não está regulado por luzes e exige precaução redobrada.','Amarelo a piscar = cruzamento perigoso, atenção.','medio','sinais-de-transito'),
('A ordem de prevalência quando existe agente de trânsito, semáforo e sinal vertical em contradição é:','Sinal vertical, semáforo, agente','Semáforo, agente, sinal vertical','Agente, semáforo, sinal vertical','Marcas na via, agente, semáforo','C','As prescrições dos agentes prevalecem sobre a sinalização luminosa, que por sua vez prevalece sobre a sinalização vertical e as marcas na via.','Pessoa manda mais que luz, luz manda mais que chapa.','medio','sinais-de-transito'),
('Um sinal triangular com a ponta para baixo significa:','Paragem obrigatória','Cedência de passagem','Fim de prioridade','Sentido proibido','B','O triângulo invertido obriga a ceder a passagem ao trânsito da via em que se vai entrar, parando se necessário.','Ponta para baixo = deixa passar quem vem.','facil','sinais-de-transito'),
('Uma linha descontínua com traços mais longos que os espaços indica:','Linha de aproximação a uma linha contínua','Zona de estacionamento','Paragem de autocarros','Faixa reservada','A','A linha de aviso antecede uma linha contínua e alerta que a ultrapassagem deve ser concluída.','Traços longos = a contínua vem aí.','dificil','sinais-de-transito'),
('Um sinal de proibição de sentido (círculo vermelho com barra branca horizontal) significa:','Estrada sem saída','Sentido proibido a todos os veículos','Proibido estacionar','Via reservada a peões','B','O sinal indica que é proibido entrar naquela via no sentido indicado.','Barra branca em círculo vermelho = não entres.','facil','sinais-de-transito'),
('Em Moçambique, a circulação faz-se:','Pela esquerda da faixa de rodagem','Pela direita da faixa de rodagem','Pelo centro da faixa de rodagem','Indiferentemente','B','Em Moçambique circula-se pela direita, mantendo-se o condutor o mais próximo possível da berma direita.','Direita sempre, exceto para ultrapassar.','facil','regras-de-transito'),
('Antes de mudar de direção, o condutor deve:','Sinalizar apenas se houver outros veículos','Sinalizar com antecedência e verificar os espelhos e ângulos mortos','Reduzir e mudar de imediato','Buzinar','B','A manobra deve ser anunciada com antecedência e só executada depois de confirmar que não cria perigo.','Espelho, sinal, manobra.','facil','regras-de-transito'),
('O uso do sinal sonoro (buzina) dentro das localidades:','É livre a qualquer hora','Só deve ser usado para evitar um acidente','Serve para cumprimentar outros condutores','É obrigatório em cruzamentos','B','A buzina destina-se a prevenir um perigo e não pode ser usada de forma abusiva, sobretudo em zonas urbanas e à noite.','A buzina é um aviso, não uma conversa.','facil','regras-de-transito'),
('Ao entrar numa via a partir de um parque de estacionamento, o condutor:','Tem prioridade sobre o trânsito da via','Deve ceder passagem ao trânsito que circula na via','Deve buzinar e avançar','Só cede a veículos pesados','B','Quem sai de um local não classificado como via pública deve ceder passagem a todos os veículos que já circulam na via.','Quem entra cede, quem já circula segue.','facil','regras-de-transito'),
('A marcha atrás deve ser executada:','A velocidade normal','Lentamente e na menor distância possível, sem criar perigo','Apenas em autoestradas','Sempre que o condutor errar a saída','B','A marcha atrás é uma manobra de recurso, feita devagar, com boa visibilidade e sem prejudicar os outros utentes.','Marcha atrás: curta, lenta e vigiada.','medio','regras-de-transito'),
('Usar o telemóvel na mão enquanto conduz:','É permitido em trânsito lento','É proibido, pois reduz a atenção e o controlo do veículo','É permitido em estradas vazias','Só é proibido de noite','B','A utilização do telemóvel na mão diminui a atenção, o campo visual e o tempo de reação, sendo uma infração.','Se precisa de falar, pare em local seguro.','facil','regras-de-transito'),
('Numa via de sentido único com duas filas de trânsito, o condutor deve:','Circular sempre na fila da esquerda','Circular na fila da direita, usando a esquerda para ultrapassar ou mudar de direção','Circular em ziguezague','Escolher a fila mais rápida','B','A regra geral é ocupar a via mais à direita, reservando a esquerda para ultrapassagens e mudanças de direção.','Esquerda é para passar, não para ficar.','medio','regras-de-transito'),
('Parar o veículo em cima de uma passadeira para peões:','É permitido durante poucos segundos','É proibido em qualquer circunstância','É permitido se não houver peões','Só é proibido de dia','B','A passadeira destina-se exclusivamente à travessia de peões e não pode ser ocupada por veículos parados.','Passadeira é chão dos peões.','facil','regras-de-transito'),
('Numa rotunda, tem prioridade:','Quem vai entrar','Quem já circula dentro da rotunda','O veículo maior','Quem entra pela direita','B','Quem pretende entrar numa rotunda deve ceder passagem aos veículos que nela já circulam.','Dentro da rotunda manda quem já lá está.','facil','prioridade'),
('Num cruzamento sem sinalização, deve ceder passagem:','A quem vem da esquerda','A quem se apresenta pela direita','Ao veículo mais rápido','A quem buzinar primeiro','B','Na ausência de sinalização e de regra especial, aplica-se a prioridade à direita.','Sem sinais, a direita manda.','facil','prioridade'),
('Um veículo de bombeiros com sinais especiais em serviço urgente:','Tem prioridade e deve ser facilitada a sua passagem','Deve respeitar a fila','Só tem prioridade em autoestradas','Tem prioridade apenas de noite','A','Os veículos em serviço urgente com luzes e sirene em funcionamento têm prioridade sobre os restantes utentes.','Sirene ligada: encoste e deixe passar.','facil','prioridade'),
('Ao sair de uma rotunda, o condutor deve:','Não sinalizar','Sinalizar para a direita antes da saída','Sinalizar para a esquerda','Acender os quatro piscas','B','A saída da rotunda é uma mudança de direção para a direita e deve ser sinalizada para informar os outros condutores.','Entrar em silêncio, sair a piscar à direita.','medio','prioridade'),
('Numa via estreita em declive acentuado, quando o cruzamento é difícil:','Deve recuar o veículo que sobe','Deve recuar o veículo que desce','Recua sempre o veículo menor','Recua quem chegar primeiro','B','Quem desce tem melhor controlo e visibilidade para recuar, pelo que deve facilitar a passagem a quem sobe.','Quem desce cede a quem sobe.','dificil','prioridade'),
('Perante um peão que já iniciou a travessia numa passadeira, o condutor:','Pode passar se for rápido','Deve parar e deixá-lo concluir a travessia','Deve buzinar','Deve passar pela retaguarda do peão','B','O peão que já se encontra na passadeira tem prioridade absoluta e o condutor deve imobilizar o veículo.','Peão na passadeira: pare, sempre.','facil','prioridade'),
('Ao aproximar-se de uma passagem de nível sem barreiras, o condutor deve:','Manter a velocidade','Reduzir, olhar para ambos os lados e certificar-se de que pode atravessar','Buzinar e passar','Parar sempre durante 30 segundos','B','A passagem de nível exige redução de velocidade e verificação visual, atravessando só quando houver total segurança.','Comboio nunca trava a tempo: verifique você.','medio','prioridade'),
('A ultrapassagem faz-se, em regra:','Pela direita','Pela esquerda','Pela berma','Pelo passeio','B','Como se circula pela direita, a ultrapassagem faz-se pela esquerda, salvo exceções previstas na lei.','Ultrapassa-se por dentro da via, à esquerda.','facil','ultrapassagem'),
('É proibido ultrapassar:','Em reta com boa visibilidade','Imediatamente antes e nas passagens para peões','Em estradas largas','Durante o dia','B','Nas imediações de passadeiras a ultrapassagem esconde peões e é proibida por criar risco elevado.','Antes da passadeira nunca se ultrapassa.','facil','ultrapassagem'),
('Antes de iniciar uma ultrapassagem o condutor deve certificar-se de que:','O veículo da frente é mais lento','Tem espaço e visibilidade suficientes para concluir a manobra sem perigo','Consegue buzinar','O troço tem linha contínua','B','A ultrapassagem só pode iniciar-se quando existe visibilidade, espaço livre e possibilidade de retomar a direita em segurança.','Se tem dúvidas, não ultrapasse.','facil','ultrapassagem'),
('Quando um condutor está a ser ultrapassado deve:','Acelerar','Manter-se à direita e não aumentar a velocidade','Travar bruscamente','Sinalizar à esquerda','B','Quem é ultrapassado deve facilitar a manobra, encostando-se à direita e mantendo velocidade constante.','Ser ultrapassado não é competição.','facil','ultrapassagem'),
('Ultrapassar em curva sem visibilidade é:','Permitido se não vier ninguém','Extremamente perigoso e proibido','Permitido de dia','Permitido para veículos ligeiros','B','Sem visibilidade não é possível avaliar o trânsito em sentido contrário, sendo a manobra proibida e potencialmente fatal.','Curva cega: fique atrás.','facil','ultrapassagem'),
('É proibido estacionar:','A mais de 5 metros de um cruzamento','Em frente a saídas de garagens e entradas de veículos','Em parques de estacionamento','Junto ao passeio, à direita','B','Estacionar em frente a entradas e saídas impede o acesso e constitui infração.','Não bloqueie a porta de ninguém.','facil','paragem-estacionamento'),
('A diferença entre paragem e estacionamento é que a paragem:','Dura mais de 5 minutos','É a imobilização pelo tempo necessário à entrada ou saída de passageiros ou carga','Só existe em autoestradas','É sempre proibida','B','A paragem é breve e ligada à entrada/saída de pessoas ou bens, com o condutor pronto a retomar a marcha.','Parar é curto; estacionar é deixar o carro.','medio','paragem-estacionamento'),
('Estacionar em segunda fila:','É permitido por poucos minutos','É proibido porque reduz a via e cria perigo','É permitido com os piscas ligados','É permitido à noite','B','A segunda fila estreita a via, obriga manobras perigosas e obstrui o trânsito, sendo proibida.','Piscas ligados não legalizam a infração.','facil','paragem-estacionamento'),
('Estacionar sobre o passeio:','É permitido se sobrar espaço','Prejudica os peões e é proibido','É permitido em zonas comerciais','Só é proibido em Maputo','B','O passeio destina-se a peões, incluindo pessoas com mobilidade reduzida e carrinhos de bebé.','Passeio é para pés, não para pneus.','facil','paragem-estacionamento'),
('Ao estacionar num declive, é aconselhável:','Deixar a caixa em ponto morto','Travar com o travão de estacionamento e engrenar uma velocidade','Deixar as luzes acesas','Virar as rodas para a faixa de rodagem','B','O travão de estacionamento combinado com uma velocidade engrenada impede que o veículo se desloque.','Em subida ou descida, trave e engrene.','medio','paragem-estacionamento'),
('Dentro das localidades, o limite geral de velocidade para automóveis ligeiros é normalmente:','40 km/h','60 km/h','80 km/h','100 km/h','B','Dentro das localidades o limite geral é de 60 km/h, salvo sinalização em contrário.','Cidade: 60 e olhos nos peões.','facil','velocidade'),
('Fora das localidades, em estrada normal, o limite geral para ligeiros é habitualmente:','60 km/h','80 km/h','100 km/h','120 km/h','C','Fora das localidades a velocidade máxima para ligeiros é geralmente 100 km/h, salvo sinalização diferente.','Estrada aberta: 100, autoestrada: 120.','medio','velocidade'),
('Em autoestrada, o limite máximo habitual para ligeiros é:','90 km/h','100 km/h','120 km/h','140 km/h','C','As autoestradas permitem circulação até 120 km/h para veículos ligeiros, salvo sinalização mais restritiva.','120 é máximo, não obrigação.','medio','velocidade'),
('Circular muito abaixo do limite sem motivo:','É sempre seguro','Pode perturbar o trânsito e constituir infração','É recomendado','Só é problema à noite','B','A marcha lenta injustificada obriga a ultrapassagens sucessivas e cria perigo, sendo sancionável.','Lento demais também é perigoso.','medio','velocidade'),
('A velocidade deve ser sempre adequada:','Ao limite indicado, apenas','Às condições da via, do veículo, do tempo e do trânsito','À pressa do condutor','Ao veículo da frente','B','O limite é um máximo; a velocidade adequada depende de chuva, visibilidade, carga e estado do piso.','O limite é teto, não meta.','facil','velocidade'),
('Duplicar a velocidade faz com que a distância de paragem:','Duplique','Aumente aproximadamente quatro vezes','Fique igual','Diminua','B','A distância de travagem cresce com o quadrado da velocidade, pelo que o dobro da velocidade quadruplica o espaço necessário.','Dobro da velocidade, quádruplo do travar.','dificil','velocidade'),
('Numa zona de obras sinalizada, o condutor deve:','Manter a velocidade','Reduzir e respeitar a sinalização temporária','Ultrapassar rapidamente','Usar a berma','B','A sinalização temporária prevalece e protege trabalhadores e utentes, exigindo redução de velocidade.','Obras: menos velocidade, mais atenção.','facil','velocidade'),
('A regra dos dois segundos serve para:','Medir o consumo','Calcular a distância de segurança em relação ao veículo da frente','Medir o tempo de ultrapassagem','Definir o tempo de paragem','B','Escolhe-se um ponto fixo e contam-se dois segundos entre a passagem do veículo da frente e a nossa; em más condições, aumenta-se.','Em chuva use quatro segundos.','medio','distancia-seguranca'),
('A distância de paragem é composta por:','Apenas a distância de travagem','Distância percorrida durante o tempo de reação mais a distância de travagem','Apenas o tempo de reação','Distância até ao sinal','B','Entre ver o perigo e travar decorre o tempo de reação, durante o qual o veículo continua a andar.','Pensar também gasta metros.','medio','distancia-seguranca'),
('Circular demasiado próximo do veículo da frente:','Poupa combustível','Reduz o campo visual e o tempo de reação','Facilita a ultrapassagem','É obrigatório em filas','B','A proximidade excessiva impede ver o trânsito à frente e torna impossível travar a tempo.','Colado atrás é acidente à espera.','facil','distancia-seguranca'),
('Com piso molhado, a distância de segurança deve:','Manter-se igual','Ser aumentada','Ser reduzida','Depender do veículo da frente','B','Com aderência reduzida a travagem é mais longa, exigindo maior intervalo.','Chuva: dobre a distância.','facil','distancia-seguranca'),
('Condução defensiva significa:','Conduzir sempre devagar','Antecipar erros dos outros e manter margens de segurança','Nunca ultrapassar','Conduzir apenas de dia','B','O condutor defensivo prevê situações de risco e mantém espaço e tempo para reagir.','Espere o erro do outro e esteja pronto.','facil','conducao-defensiva'),
('Ao aproximar-se de um autocarro parado numa paragem, o condutor deve:','Acelerar para passar','Reduzir e prever a saída de peões à frente do autocarro','Buzinar','Passar pela berma','B','Peões atravessam frequentemente à frente ou atrás do autocarro, fora do campo de visão.','Autocarro parado esconde peões.','medio','conducao-defensiva'),
('Numa fila de trânsito parada, o mais seguro é:','Manter-se colado ao veículo da frente','Deixar espaço suficiente para ver os pneus do veículo da frente','Sair da fila pela berma','Desligar o motor','B','Esse espaço permite contornar o veículo da frente em caso de avaria ou emergência e evita colisões em cadeia.','Ver os pneus é ver a saída.','medio','conducao-defensiva'),
('O ângulo morto é:','Uma zona da estrada sem iluminação','Uma zona não visível pelos espelhos retrovisores','O ponto cego do para-brisas','A zona atrás do banco','B','O ângulo morto exige um olhar rápido por cima do ombro antes de mudar de via.','Espelho não chega: olhe por cima do ombro.','facil','conducao-defensiva'),
('Ao ser encandeado por um veículo em sentido contrário, deve:','Fixar o olhar nos faróis','Desviar o olhar para a margem direita e reduzir a velocidade','Ligar os máximos','Fechar os olhos por instantes','B','Olhar para a margem direita mantém a referência da via enquanto se evita o encandeamento.','Olhe para a linha da direita.','medio','conducao-defensiva'),
('O álcool, mesmo em pequenas quantidades:','Melhora os reflexos','Aumenta o tempo de reação e diminui a perceção do risco','Não afeta a condução','Só afeta condutores novos','B','O álcool atua no sistema nervoso central, reduzindo a atenção, a coordenação e a avaliação do perigo.','Se bebeu, não conduza. Sem exceções.','facil','alcool'),
('Beber café ou tomar duche depois de consumir álcool:','Elimina o álcool do sangue','Não reduz a taxa de álcool no sangue','Reduz a taxa para metade','Anula os efeitos','B','Apenas o tempo permite ao organismo metabolizar o álcool; nenhum truque acelera esse processo.','Só o tempo tira o álcool.','facil','alcool'),
('Conduzir sob influência do álcool aumenta sobretudo:','A visão periférica','O risco de acidente grave','A capacidade de julgamento','A distância de segurança','B','A combinação de reflexos lentos e excesso de confiança multiplica o risco de acidente.','Álcool dá coragem falsa e reflexos lentos.','facil','alcool'),
('A mistura de álcool com medicamentos:','É inofensiva','Pode potenciar os efeitos e agravar a sonolência','Melhora a atenção','Só é perigosa para idosos','B','Muitos medicamentos interagem com o álcool, aumentando a sedação e a perda de coordenação.','Leia sempre a bula antes de conduzir.','medio','alcool'),
('Um condutor que se sente ligeiramente alegre depois de beber:','Já tem as capacidades de condução alteradas','Está apto a conduzir','Conduz melhor','Só não pode conduzir de noite','A','A euforia é já um sinal de efeito no sistema nervoso, com perda de autocrítica.','Sentir-se bem não é estar apto.','medio','alcool'),
('Perante os primeiros sinais de sonolência ao volante, o condutor deve:','Abrir a janela e continuar','Parar em local seguro e descansar','Aumentar o volume do rádio','Beber café e acelerar','B','A única solução eficaz é parar e dormir uma sesta curta; os restantes truques dão falsa segurança.','Sono ao volante só se resolve dormindo.','facil','fadiga'),
('Em viagens longas recomenda-se fazer pausas:','A cada 8 horas','Aproximadamente a cada 2 horas','Apenas quando houver bombas','Só quando o condutor bocejar','B','Pausas regulares de cerca de 15 minutos a cada 2 horas reduzem significativamente a fadiga.','2 horas ao volante, 15 minutos de pausa.','facil','fadiga'),
('A microssonolência é:','Um breve adormecimento de segundos sem o condutor perceber','Uma doença rara','Um efeito do frio','Um tipo de distração sonora','A','Alguns segundos de microssono a 100 km/h significam dezenas de metros percorridos sem controlo.','2 segundos a dormir = 55 metros às cegas.','dificil','fadiga'),
('Conduzir depois de uma noite mal dormida:','É seguro se o percurso for curto','Reduz a atenção de forma comparável ao consumo de álcool','Melhora a concentração','Só afeta condutores idosos','B','A privação de sono degrada o tempo de reação e o julgamento de forma semelhante ao álcool.','Dormir pouco é conduzir alcoolizado.','medio','fadiga'),
('Perante um condutor agressivo que buzina e pisca as luzes, o mais correto é:','Responder da mesma forma','Manter a calma, facilitar a passagem e não entrar em confronto','Travar bruscamente','Acelerar para o afastar','B','Responder à agressividade aumenta o risco; ceder espaço resolve a situação em segurança.','Não conduza com o ego.','facil','comportamento'),
('O stress ao volante tende a:','Melhorar a concentração','Aumentar erros de avaliação e comportamentos de risco','Reduzir a velocidade','Não ter efeito','B','O stress estreita a atenção e favorece decisões impulsivas.','Se está tenso, respire e abrande.','medio','comportamento'),
('Conduzir com pressa constante:','É sinal de perícia','Aumenta a probabilidade de infrações e acidentes','Poupa tempo significativo','Melhora a antecipação','B','A pressa leva a manobras arriscadas e ganha, no fim, muito pouco tempo real.','Sair 10 minutos antes vale mais que correr.','facil','comportamento'),
('A cortesia no trânsito:','É desnecessária','Contribui para a fluidez e reduz conflitos','Atrasa sempre o trânsito','Só se aplica a peões','B','Ceder passagem e comunicar intenções torna o trânsito mais previsível e seguro.','Trânsito previsível é trânsito seguro.','facil','comportamento'),
('O cinto de segurança deve ser usado:','Só pelo condutor','Por todos os ocupantes, à frente e atrás','Só em autoestradas','Só em viagens longas','B','Todos os ocupantes devem usar cinto; um passageiro sem cinto pode ferir gravemente os outros numa colisão.','Atrás sem cinto é projétil.','facil','seguranca-rodoviaria'),
('O airbag é um sistema:','Que substitui o cinto de segurança','Complementar ao cinto de segurança','Que só funciona a baixa velocidade','Decorativo','B','O airbag foi concebido para funcionar com o cinto; sem cinto pode até agravar lesões.','Airbag ajuda, cinto salva.','facil','seguranca-rodoviaria'),
('As crianças devem viajar:','Ao colo de um adulto','Em sistema de retenção adequado à idade, altura e peso','No banco da frente sempre','Sem cinto se forem baixas','B','As cadeirinhas homologadas distribuem as forças do impacto de forma adequada ao corpo da criança.','Colo não é cadeirinha.','facil','seguranca-rodoviaria'),
('O apoio de cabeça bem ajustado protege sobretudo:','A coluna cervical em caso de colisão traseira','Os joelhos','A visão','Os ombros apenas','A','Um apoio de cabeça à altura do topo da cabeça reduz o efeito de chicote nas colisões traseiras.','Topo do apoio ao nível do topo da cabeça.','medio','seguranca-rodoviaria'),
('Objetos soltos dentro do veículo:','São inofensivos','Podem transformar-se em projéteis numa travagem brusca','Ajudam a equilibrar o carro','Só são perigosos em autoestrada','B','Numa colisão, um objeto multiplica o seu peso pela desaceleração, tornando-se um projétil.','Arrume tudo antes de arrancar.','medio','seguranca-rodoviaria'),
('O capacete para condutores de motociclos:','É opcional em vias urbanas','É obrigatório e deve estar devidamente apertado','Só é obrigatório em autoestradas','Só é obrigatório de noite','B','O capacete homologado e bem apertado é a principal proteção do motociclista.','Capacete solto não protege.','facil','seguranca-rodoviaria'),
('À noite, fora das localidades e sem trânsito em sentido contrário, deve usar:','Luzes de presença','Luzes de estrada (máximos)','Luzes de nevoeiro','Quatro piscas','B','Os máximos aumentam o alcance de visão; devem ser reduzidos ao cruzar ou seguir outro veículo.','Máximos sim, mas nunca a encandear.','facil','conducao-noturna'),
('Ao cruzar-se com outro veículo à noite, deve:','Manter os máximos','Passar para luzes de cruzamento (médios)','Apagar as luzes','Usar quatro piscas','B','Os médios evitam encandear o condutor em sentido contrário, prevenindo acidentes.','Cruzou? Médios.','facil','conducao-noturna'),
('A condução noturna é mais exigente porque:','O trânsito é maior','A visibilidade e a perceção de distâncias diminuem','As estradas são piores','A velocidade é maior','B','À noite o campo visual reduz-se ao alcance dos faróis e a perceção de velocidade e distância é distorcida.','De noite conduza dentro dos faróis.','medio','conducao-noturna'),
('As luzes de nevoeiro traseiras devem ser usadas:','Sempre à noite','Apenas com visibilidade muito reduzida','Em autoestradas','Quando chove ligeiramente','B','Usadas indevidamente, encandeiam quem vem atrás e escondem as luzes de travagem.','Nevoeiro traseiro só quando quase não se vê.','medio','conducao-noturna'),
('Faróis desalinhados ou sujos:','Não afetam a segurança','Reduzem o alcance da iluminação e podem encandear os outros','Melhoram a visibilidade','Só importam de dia','B','A manutenção dos faróis é essencial para ver e ser visto em condições de baixa luminosidade.','Faróis limpos, noite mais segura.','facil','conducao-noturna'),
('A aquaplanagem ocorre quando:','Os travões aquecem','Uma camada de água impede o contacto dos pneus com o piso','O motor falha','A direção fica pesada','B','Com água acumulada e velocidade elevada, o pneu deixa de escoar água e perde aderência.','Água + velocidade = pneu a flutuar.','medio','aquaplanagem'),
('Em situação de aquaplanagem, o condutor deve:','Travar a fundo','Tirar o pé do acelerador e manter a direção firme, sem travar bruscamente','Virar rapidamente','Acelerar','B','Travar ou virar bruscamente provoca despiste; a recuperação faz-se com suavidade até os pneus voltarem a agarrar.','Solte o pé e segure o volante.','dificil','aquaplanagem'),
('O risco de aquaplanagem aumenta com:','Pneus novos','Pneus com pouco piso e velocidade elevada','Pouco peso no carro','Estradas secas','B','A profundidade dos sulcos é o que permite escoar a água; pneus gastos perdem essa capacidade.','Pneu careca é pneu de patinagem.','facil','aquaplanagem'),
('Depois de atravessar uma zona alagada, é aconselhável:','Acelerar','Travar levemente para secar os travões','Desligar o motor','Nada de especial','B','Travagens ligeiras aquecem e secam os discos, restabelecendo a eficácia dos travões.','Água nos travões: trave devagar para secar.','medio','aquaplanagem'),
('Com nevoeiro denso, o condutor deve:','Ligar os máximos','Reduzir a velocidade e usar luzes de nevoeiro ou médios','Seguir colado ao carro da frente','Parar na faixa de rodagem','B','Os máximos refletem no nevoeiro e reduzem ainda mais a visibilidade.','Nevoeiro: médios, devagar e sem colar.','medio','meteorologia'),
('Com vento lateral forte, o condutor deve:','Aumentar a velocidade','Segurar firmemente o volante e reduzir a velocidade','Conduzir com uma mão','Aproximar-se de camiões','B','As rajadas desviam o veículo, sobretudo ao sair de zonas abrigadas ou ao ultrapassar pesados.','Vento lateral: mãos firmes, pé leve.','medio','meteorologia'),
('As primeiras gotas de chuva após um período seco tornam o piso:','Mais aderente','Especialmente escorregadio devido à mistura de poeiras e óleos','Igual','Mais rugoso','B','A película de óleo e poeira levantada pela chuva reduz drasticamente a aderência.','A chuva mais perigosa é a que começa.','medio','meteorologia'),
('Em caso de chuva intensa que impede a visibilidade:','Deve parar na berma com as luzes ligadas ou em local seguro','Deve manter a velocidade','Deve seguir pelo meio da estrada','Deve desligar as luzes','A','Quando a visibilidade é nula, o mais seguro é parar em local que não constitua obstáculo e sinalizar a presença.','Se não vê, também não é visto.','medio','meteorologia'),
('Ao aproximar-se de crianças na berma da estrada, o condutor deve:','Manter a velocidade','Reduzir a velocidade e estar preparado para parar','Buzinar continuamente','Passar o mais depressa possível','B','As crianças têm comportamentos imprevisíveis e pouca noção de velocidade e distância.','Criança na berma: pé no travão.','facil','peoes-velocipedes'),
('Ao ultrapassar um velocípede, o condutor deve:','Passar rente','Deixar uma distância lateral de segurança','Buzinar antes de passar','Acelerar bruscamente','B','O ciclista pode oscilar por causa do vento ou de buracos, exigindo folga lateral suficiente.','Dê espaço ao ciclista, ele não tem carroçaria.','facil','peoes-velocipedes'),
('Um peão idoso a atravessar lentamente:','Deve ser apressado com a buzina','Deve poder concluir a travessia sem pressão','Pode ser ultrapassado pela frente','Deve ser ignorado','B','Os peões idosos são utentes vulneráveis e podem precisar de mais tempo para atravessar.','Paciência custa segundos, atropelar custa vidas.','facil','peoes-velocipedes'),
('Onde não existirem passeios, os peões devem circular:','Pelo meio da via','Pela berma, preferencialmente pela esquerda, de frente para o trânsito','Sempre pela direita','Apenas de noite','B','Circular de frente para o trânsito permite ao peão ver os veículos que se aproximam.','Peão anda de frente para os carros.','medio','peoes-velocipedes'),
('Os veículos pesados, em comparação com os ligeiros:','Travam em menos espaço','Necessitam de maior distância de travagem','São mais fáceis de manobrar','Têm melhor visibilidade traseira','B','A massa elevada aumenta a energia a dissipar, exigindo distâncias de paragem muito maiores.','Nunca trave à frente de um camião.','facil','veiculos-pesados'),
('Ao seguir atrás de um camião, o condutor deve:','Colar-se para poupar combustível','Manter maior distância para ver melhor a estrada','Circular na diagonal','Buzinar','B','Maior distância aumenta o campo de visão e o tempo de reação, e permite ser visto pelo condutor do pesado.','Se não vê os espelhos dele, ele não o vê.','facil','veiculos-pesados'),
('Nas curvas, os veículos longos:','Ocupam menos espaço','Podem invadir a via contígua devido ao raio de viragem','Viram mais depressa','Não precisam de sinalizar','B','O eixo traseiro descreve uma trajetória mais curta, obrigando o veículo a ocupar espaço adicional.','Camião a virar: fique atrás e espere.','medio','veiculos-pesados'),
('Em caso de acidente, a primeira ação deve ser:','Tirar fotografias','Sinalizar o local e garantir a segurança de todos','Discutir responsabilidades','Mover imediatamente os feridos','B','Proteger o local evita acidentes secundários; só depois se socorre e se contactam as autoridades.','Proteger, alertar, socorrer.','facil','acidentes-emergencia'),
('Um ferido inconsciente que respira deve:','Ser levantado e sentado','Ser mantido em posição lateral de segurança, se não houver suspeita de lesão na coluna','Receber água','Ser deixado de barriga para cima sempre','B','A posição lateral de segurança evita a obstrução das vias respiratórias por vómito ou pela língua.','Inconsciente que respira: deite de lado.','dificil','acidentes-emergencia'),
('O triângulo de pré-sinalização deve ser colocado:','Junto ao veículo','A distância suficiente para ser visto atempadamente pelos outros condutores','No banco do condutor','Apenas de noite','B','A colocação deve permitir que quem se aproxima tenha tempo de reduzir e desviar-se em segurança.','Coloque o triângulo bem antes do carro.','facil','acidentes-emergencia'),
('Retirar o capacete a um motociclista acidentado:','Deve ser feito sempre e de imediato','Só deve ser feito por pessoal habilitado, salvo risco imediato de morte','É obrigatório para o identificar','Facilita a respiração sempre','B','A remoção incorreta pode agravar lesões cervicais graves.','Capacete fica, salvo emergência vital.','dificil','acidentes-emergencia'),
('Fugir do local de um acidente com feridos:','É admissível se houver pressa','É uma infração grave e crime de omissão de auxílio','Só é grave à noite','É permitido se chamar ajuda depois','B','A lei impõe o dever de permanecer, socorrer e identificar-se.','Nunca abandone o local.','facil','acidentes-emergencia'),
('A pressão dos pneus deve ser verificada:','Uma vez por ano','Regularmente e com os pneus frios','Só antes de viagens longas','Apenas quando o pneu parece vazio','B','A pressão correta garante aderência, estabilidade e menor consumo; a medição a quente falseia o valor.','Pneus frios dão a leitura certa.','facil','mecanica'),
('Um pneu com pressão insuficiente provoca:','Menor consumo','Maior desgaste dos ombros do pneu e risco de rebentamento','Melhor travagem','Direção mais leve','B','A flexão excessiva aquece o pneu e degrada a sua estrutura.','Pneu vazio aquece e rebenta.','medio','mecanica'),
('O líquido dos travões deve ser:','Verificado apenas em oficina de marca','Verificado periodicamente e substituído conforme o fabricante','Ignorado','Misturado com água','B','O líquido absorve humidade ao longo do tempo, reduzindo a eficácia da travagem.','Travões pedem manutenção, não sorte.','medio','mecanica'),
('Se a luz vermelha da temperatura do motor acender, deve:','Continuar a viagem','Parar em segurança e deixar o motor arrefecer','Acelerar para arrefecer','Desligar os travões','B','Prosseguir com sobreaquecimento pode destruir o motor.','Vermelho no painel: pare já.','facil','mecanica'),
('Os pneus devem ser substituídos quando:','A borracha muda de cor','A profundidade dos sulcos atinge o limite legal mínimo','Completarem um ano','Ficarem sujos','B','Sem sulcos suficientes o pneu perde a capacidade de escoar água e aderir ao piso.','Sulco raso, travagem longa.','medio','mecanica'),
('A categoria B da carta de condução permite conduzir, em regra:','Motociclos pesados','Automóveis ligeiros até 3500 kg','Camiões pesados','Autocarros','B','A categoria B abrange automóveis ligeiros com peso bruto até 3500 kg e lotação até 9 lugares.','B é de carro ligeiro.','facil','categorias-carta'),
('A carta de condução deve ser apresentada:','Apenas quando houver acidente','Sempre que solicitada por agente de autoridade','Só em viagens longas','Apenas com fotocópia','B','Conduzir sem documentos e não os apresentar quando solicitados constitui infração.','Documentos sempre consigo.','facil','categorias-carta'),
('Conduzir um veículo de categoria não autorizada pela carta:','É permitido em emergências','É infração grave e pode invalidar o seguro','É permitido em vias urbanas','Depende do veículo','B','Conduzir fora da categoria titulada equivale a conduzir sem habilitação para aquele veículo.','Só conduza o que a carta permite.','medio','categorias-carta'),
('A carta de condução caducada:','Continua válida por um ano','Não habilita à condução até ser revalidada','Só é problema em autoestradas','Serve como identificação para conduzir','B','A validade é condição da habilitação; conduzir com título caducado é infração.','Marque a revalidação com antecedência.','medio','categorias-carta'),
('Exceder o limite de velocidade constitui:','Uma recomendação ignorada','Uma contraordenação sancionada com multa e eventualmente outras medidas','Um crime sempre','Uma falta apenas de noite','B','O excesso de velocidade é uma das infrações mais sancionadas por estar associada à gravidade dos acidentes.','Velocidade é a causa que mais mata.','facil','contraordenacoes'),
('Conduzir sem seguro obrigatório:','É permitido em percursos curtos','É infração e deixa o condutor responsável por todos os danos','Só é problema em acidente grave','É permitido com carta válida','B','O seguro de responsabilidade civil é obrigatório e protege terceiros.','Sem seguro, paga do seu bolso.','facil','contraordenacoes'),
('Estacionar em lugar reservado a pessoas com deficiência sem direito:','É tolerado por pouco tempo','É infração e prejudica quem realmente precisa','É permitido aos fins de semana','Depende do parque','B','Estes lugares são dimensionados e localizados para necessidades específicas de mobilidade.','Aquele lugar não é seu.','facil','contraordenacoes'),
('Recusar-se ao teste de alcoolemia:','Não tem consequências','É sancionado, podendo ser equiparado à condução sob influência','É um direito do condutor','Só é sancionado em acidente','B','A recusa impede a fiscalização e é punida de forma severa.','Recusar não é escapar.','medio','contraordenacoes'),
('Numa zona residencial com peões, o condutor deve:','Circular a velocidade reduzida e com máxima atenção','Manter o limite geral','Buzinar para avisar','Usar máximos','A','Nestas zonas, peões e crianças partilham o espaço e a velocidade deve permitir parar de imediato.','Bairro é para viver, não para correr.','facil','zonas-urbanas'),
('Em filas de trânsito urbano, bloquear um cruzamento:','É inevitável','Deve ser evitado, avançando só quando houver espaço para sair','É permitido com piscas','É permitido nas horas de ponta','B','Entrar num cruzamento sem espaço de saída paralisa as vias transversais.','Só entre se puder sair.','medio','zonas-urbanas'),
('Nas vias urbanas com transportes públicos, o condutor deve:','Ignorar as faixas BUS','Respeitar as faixas reservadas e facilitar a saída dos autocarros das paragens','Circular sempre na faixa BUS','Ultrapassar pela direita','B','As faixas reservadas garantem eficiência do transporte público e o seu uso indevido é infração.','Faixa BUS não é atalho.','medio','zonas-urbanas'),
('Ao circular junto a mercados e escolas:','A velocidade deve ser reduzida e a vigilância aumentada','Pode manter-se o limite máximo','Deve usar-se a buzina em permanência','Deve circular-se pela berma','A','Nestes locais a densidade de peões e as travessias imprevistas são elevadas.','Escola e mercado: pé fora do acelerador.','facil','zonas-urbanas'),
('Em estradas nacionais sem berma pavimentada, o condutor deve:','Circular junto ao eixo da via','Manter-se à direita, atento a peões e animais na berma','Usar sempre máximos','Ultrapassar pela berma','B','Fora das localidades é frequente a presença de peões, bicicletas e animais na berma.','Fora da cidade a berma tem vida.','medio','fora-localidades'),
('Ao aproximar-se de uma povoação sinalizada, o condutor deve:','Manter a velocidade da estrada','Reduzir para o limite aplicável dentro da localidade','Acelerar para passar rápido','Usar as quatro piscas','B','O sinal de localidade marca o início das regras urbanas, incluindo o limite geral mais baixo.','Placa da povoação: abrande já.','facil','fora-localidades'),
('Em estradas com animais na via:','Deve acelerar para os afastar','Deve reduzir, parar se necessário e evitar manobras bruscas','Deve buzinar continuamente','Deve passar pela berma','B','Manobras bruscas provocam despistes; a redução controlada é mais segura.','Animal na via: travar reto, não desviar bruscamente.','medio','fora-localidades'),
('Em autoestrada é proibido:','Circular a 100 km/h','Inverter o sentido de marcha e fazer marcha atrás','Ultrapassar pela esquerda','Usar a via da direita','B','A inversão de marcha e a marcha atrás em autoestrada são manobras extremamente perigosas e proibidas.','Errou a saída? Saia na seguinte.','facil','autoestradas'),
('A via mais à esquerda da autoestrada destina-se a:','Circulação normal','Ultrapassagens','Veículos pesados','Paragens de emergência','B','Concluída a ultrapassagem, o condutor deve regressar à via mais à direita disponível.','Ultrapassou? Volte à direita.','facil','autoestradas'),
('A berma da autoestrada pode ser utilizada:','Para circular em filas','Apenas em situações de emergência ou avaria','Para ultrapassar','Para estacionar e descansar','B','A berma é um espaço de segurança reservado a emergências e veículos de socorro.','Berma é para emergências, não para pressas.','facil','autoestradas'),
('Ao entrar na autoestrada pela via de aceleração, o condutor deve:','Entrar devagar','Adaptar a velocidade à do trânsito e ceder passagem antes de se inserir','Parar no final da via','Forçar a entrada','B','A via de aceleração serve para igualar a velocidade e encontrar um espaço seguro para entrar.','Acelere na via de aceleração.','medio','autoestradas'),
('Em caso de avaria em autoestrada, o condutor deve:','Ficar dentro do veículo na faixa de rodagem','Sinalizar, sair pelo lado seguro e aguardar atrás dos rails','Empurrar o carro para a via','Caminhar pela faixa de rodagem','B','Permanecer no veículo ou na via é a principal causa de atropelamentos em autoestrada.','Fora do carro e atrás do rail.','medio','autoestradas')
) AS v(qt,a,b,c,d,ca,ex,tp,df,slug)
JOIN public.categories c ON c.slug = v.slug;